def format_ref_label(ref_type, ref_name, head_branch=None):
    """Format a ref label with brackets."""
    if ref_type == 'head':
        return f"[{ref_name}]"
    elif ref_type == 'branch':
        return f"[{ref_name}]"
    elif ref_type == 'remote':
        return f"{{{ref_name}}}"
    elif ref_type == 'tag':
        return f"<{ref_name}>"
    elif ref_type == 'local-tag':
        return f"<{ref_name}>"
    elif ref_type == 'stash':
        return f"[{ref_name}]"
    else:
        return f"[{ref_name}]"


class View:
    """Base class for all tig views."""

    VIEW_NAME = "view"

    def __init__(self, app):
        self.app = app
        self.lines = []  # List of TigLine objects
        self.cursor = 0
        self.offset = 0  # scroll offset
        self.col_offset = 0  # horizontal scroll
        self.loaded = False
        self.title = ""
        self.search_pattern = None
        self.search_match_line = -1
        self.needs_refresh = True
        self.win = None
        self.height = 0
        self.width = 0
        self.y = 0
        self.x = 0
        self.status_extra = ""

    def resize(self, height, width, y, x):
        self.height = height
        self.width = width
        self.y = y
        self.x = x
        if self.win:
            try:
                self.win.resize(height, width)
                self.win.mvwin(y, x)
            except:
                pass
        else:
            try:
                self.win = curses.newwin(height, width, y, x)
            except:
                pass

    def load(self, *args, **kwargs):
        """Load data into the view."""
        pass

    def refresh(self):
        """Redraw the view."""
        if not self.win:
            return
        win = self.win
        win.erase()

        visible_height = self.height
        for i in range(visible_height):
            line_idx = self.offset + i
            if line_idx >= len(self.lines):
                break
            line = self.lines[line_idx]
            is_cursor = (line_idx == self.cursor)
            self.draw_line(win, i, line, is_cursor)

        win.noutrefresh()

    def draw_line(self, win, y, line, is_cursor):
        """Draw a single line."""
        text = line.text
        # Horizontal scroll
        if self.col_offset > 0:
            if len(text) > self.col_offset:
                text = text[self.col_offset:]
            else:
                text = ""

        # Truncate to width
        max_w = self.width - 1

        if is_cursor:
            attr = curses.color_pair(CP_CURSOR) | curses.A_BOLD
            # Draw full line with cursor color
            try:
                win.move(y, 0)
                win.clrtoeol()
                display = text[:max_w]
                win.addstr(y, 0, display, attr)
                # Fill rest with cursor
                if len(display) < max_w:
                    win.addstr(' ' * (max_w - len(display)), attr)
            except curses.error:
                pass
        else:
            attr = self.get_line_attr(line)
            try:
                win.move(y, 0)
                win.clrtoeol()
                self.draw_colored_line(win, y, line, attr, max_w)
            except curses.error:
                pass

    def get_line_attr(self, line):
        """Get attribute for a line."""
        return curses.color_pair(CP_DEFAULT)

    def draw_colored_line(self, win, y, line, default_attr, max_w):
        """Draw line with syntax highlighting. Override in subclasses."""
        text = line.text
        if self.col_offset > 0:
            text = text[self.col_offset:] if len(text) > self.col_offset else ""
        try:
            win.addstr(y, 0, text[:max_w], default_attr)
        except curses.error:
            pass

    def scroll_down(self, n=1):
        max_cursor = len(self.lines) - 1
        if max_cursor < 0:
            return
        new_cursor = min(self.cursor + n, max_cursor)
        self.cursor = new_cursor
        # Adjust offset so cursor is visible
        if self.cursor >= self.offset + self.height:
            self.offset = self.cursor - self.height + 1

    def scroll_up(self, n=1):
        new_cursor = max(self.cursor - n, 0)
        self.cursor = new_cursor
        if self.cursor < self.offset:
            self.offset = self.cursor

    def page_down(self):
        self.scroll_down(max(1, self.height - 1))

    def page_up(self):
        self.scroll_up(max(1, self.height - 1))

    def half_page_down(self):
        self.scroll_down(max(1, self.height // 2))

    def half_page_up(self):
        self.scroll_up(max(1, self.height // 2))

    def first_line(self):
        self.cursor = 0
        self.offset = 0

    def last_line(self):
        if self.lines:
            self.cursor = len(self.lines) - 1
            self.offset = max(0, self.cursor - self.height + 1)

    def scroll_line_down(self):
        """Scroll view down one line (without moving cursor)."""
        if self.offset + self.height < len(self.lines):
            self.offset += 1
            if self.cursor < self.offset:
                self.cursor = self.offset

    def scroll_line_up(self):
        """Scroll view up one line."""
        if self.offset > 0:
            self.offset -= 1
            if self.cursor >= self.offset + self.height:
                self.cursor = self.offset + self.height - 1

    def scroll_left(self, n=2):
        self.col_offset = max(0, self.col_offset - n)

    def scroll_right(self, n=2):
        self.col_offset += n

    def scroll_first_col(self):
        self.col_offset = 0

    def get_status_info(self):
        """Get the status bar info string."""
        total = len(self.lines)
        if total == 0:
            return f"[{self.VIEW_NAME}] Nothing to display"

        line_num = self.cursor + 1
        pct = int(100 * (self.offset + self.height) / total) if total > 0 else 100
        pct = min(100, pct)

        info = self.get_view_info()
        if info:
            return f"[{self.VIEW_NAME}] {info} - line {line_num} of {total}"
        return f"[{self.VIEW_NAME}] - line {line_num} of {total}"

    def get_view_info(self):
        """Get view-specific info for status bar."""
        return ""

    def get_scroll_pct(self):
        """Get scroll percentage."""
        total = len(self.lines)
        if total == 0:
            return 100
        if self.offset + self.height >= total:
            return 100
        return int(100 * (self.offset + self.height) / total)

    def search(self, pattern, forward=True):
        """Search for pattern in view."""
        if not pattern:
            return
        self.search_pattern = pattern

        try:
            regex = re.compile(pattern, re.IGNORECASE)
        except re.error:
            return

        n = len(self.lines)
        start = self.cursor

        if forward:
            indices = list(range(start + 1, n)) + list(range(0, start + 1))
        else:
            indices = list(range(start - 1, -1, -1)) + list(range(n - 1, start - 1, -1))

        for i in indices:
            if regex.search(self.lines[i].text):
                self.cursor = i
                if self.cursor < self.offset:
                    self.offset = self.cursor
                elif self.cursor >= self.offset + self.height:
                    self.offset = self.cursor - self.height + 1
                return i, self.get_match_count(regex)

        return -1, 0

    def get_match_count(self, regex):
        count = 0
        for line in self.lines:
            if regex.search(line.text):
                count += 1
        return count

    def enter(self):
        """Handle Enter key - open selected item."""
        return None

    def get_selected_line(self):
        if 0 <= self.cursor < len(self.lines):
            return self.lines[self.cursor]
        return None

