class PagerView(View):
    """Generic pager view for displaying text."""

    VIEW_NAME = "pager"

    def load_from_lines(self, text_lines):
        self.lines = []
        for line in text_lines:
            lt = self.classify_line(line)
            self.lines.append(TigLine(line, lt))
        self.loaded = True
        self.title = "pager"

    def load_from_stdin(self, text):
        lines = text.splitlines()
        self.load_from_lines(lines)

    def classify_line(self, line):
        """Classify a line for syntax highlighting."""
        if line.startswith('diff --git'):
            return LINE_DIFF_HEADER
        elif line.startswith('diff --'):
            return LINE_DIFF_HEADER
        elif line.startswith('index '):
            return LINE_DIFF_INDEX
        elif line.startswith('--- ') or line.startswith('+++ '):
            return LINE_DIFF_INDEX
        elif line.startswith('@@ '):
            return LINE_DIFF_CHUNK
        elif line.startswith('+'):
            return LINE_DIFF_ADD
        elif line.startswith('-'):
            return LINE_DIFF_DEL
        elif line.startswith('commit '):
            return LINE_COMMIT
        elif line.startswith('Merge:'):
            return LINE_MERGE
        elif line.startswith('Author:') or line.startswith('AuthorDate:'):
            return LINE_AUTHOR
        elif line.startswith('Commit:') or line.startswith('CommitDate:'):
            return LINE_COMMITTER
        elif line.startswith('Date:'):
            return LINE_DATE
        elif line.startswith('Refs:'):
            return LINE_REFS
        else:
            return LINE_DEFAULT

    def draw_colored_line(self, win, y, line, default_attr, max_w):
        text = line.text
        if self.col_offset > 0:
            text = text[self.col_offset:] if len(text) > self.col_offset else ""

        attr = self.get_line_attr(line)
        try:
            win.addstr(y, 0, text[:max_w], attr)
        except curses.error:
            pass

    def get_line_attr(self, line):
        lt = line.line_type
        if lt == LINE_DIFF_HEADER:
            return curses.color_pair(CP_DIFF_HEADER) | curses.A_BOLD
        elif lt == LINE_DIFF_INDEX:
            return curses.color_pair(CP_DIFF_INDEX)
        elif lt == LINE_DIFF_CHUNK:
            return curses.color_pair(CP_DIFF_CHUNK) | curses.A_BOLD
        elif lt == LINE_DIFF_ADD:
            return curses.color_pair(CP_DIFF_ADD)
        elif lt == LINE_DIFF_DEL:
            return curses.color_pair(CP_DIFF_DEL)
        elif lt == LINE_COMMIT:
            return curses.color_pair(CP_ID) | curses.A_BOLD
        elif lt == LINE_REFS:
            return curses.color_pair(CP_MAIN_REF)
        elif lt == LINE_AUTHOR:
            return curses.color_pair(CP_AUTHOR)
        elif lt == LINE_COMMITTER:
            return curses.color_pair(CP_COMMITTER)
        elif lt == LINE_DATE:
            return curses.color_pair(CP_DATE)
        elif lt == LINE_MERGE:
            return curses.color_pair(CP_DIFF_STAT)
        else:
            return curses.color_pair(CP_DEFAULT)

    def get_view_info(self):
        return "pager"


