                    self.lines.append(TigLine(f"  ({status[0]}) {filename}", LINE_STAT_UNSTAGED,
                                              {'status': status, 'file': filename, 'section': 'unstaged'}))

        if not unstaged_files:
            self.lines.append(TigLine("  (no files)", LINE_STAT_NONE))

        # Get untracked files
        untracked_out, _, _ = run_git(['ls-files', '--others', '--exclude-standard'], cwd=cwd)
        self.lines.append(TigLine("Untracked files:", LINE_HEADER))

        untracked_files = []
        if untracked_out.strip():
