        elif line.line_type == LINE_HEADER:
            attr = curses.color_pair(CP_HEADER) | curses.A_BOLD
        elif line.line_type == LINE_STAT_STAGED:
            attr = curses.color_pair(CP_STAT_STAGED)
        elif line.line_type == LINE_STAT_UNSTAGED:
            attr = curses.color_pair(CP_STAT_UNSTAGED)
        elif line.line_type == LINE_STAT_UNTRACKED:
            attr = curses.color_pair(CP_STAT_UNTRACKED)
        else:
