    def __init__(self, app):
        super().__init__(app)
        self.cwd = None

    def load(self, extra_args=None, cwd=None):
        self.cwd = cwd
        self.lines = []

        # Header line
        self.lines.append(TigLine("                            All references", LINE_HEADER))

        # Get all refs
        args = ['for-each-ref', '--sort=-version:refname', '--sort=-creatordate',
                '--format=%(creatordate:format:%Y-%m-%d %H:%M %z) %(authorname) %(refname:short) %(subject)',
                'refs/heads', 'refs/remotes', 'refs/tags']

        if extra_args:
            # Handle --branches, --remotes, --tags
            ref_dirs = []
            for arg in extra_args:
                if arg == '--branches':
                    ref_dirs.append('refs/heads')
                elif arg == '--remotes':
                    ref_dirs.append('refs/remotes')
                elif arg == '--tags':
                    ref_dirs.append('refs/tags')
            if ref_dirs:
                args = ['for-each-ref', '--sort=-version:refname', '--sort=-creatordate',
                       '--format=%(creatordate:format:%Y-%m-%d %H:%M %z) %(authorname) %(refname:short) %(subject)'] + ref_dirs

        out, err, rc = run_git(args, cwd=cwd)

        if rc != 0:
            self.lines.append(TigLine("No references found"))
            self.loaded = True
            return

        # Get HEAD branch
        head_out, _, _ = run_git(['symbolic-ref', '--short', 'HEAD'], cwd=cwd)
        head_branch = head_out.strip()

        for line in out.splitlines():
            # Format: date author refname subject
            parts = line.split(' ', 4)
            if len(parts) < 4:
                continue

            date_part = ' '.join(parts[:3])
            author = parts[3] if len(parts) > 3 else ''
            rest = parts[4] if len(parts) > 4 else ''

            # Parse refname and subject
            rest_parts = rest.split(' ', 1)
            refname = rest_parts[0]
            subject = rest_parts[1] if len(rest_parts) > 1 else ''

            # Format like tig: date author refname subject
            text = f"{date_part} {author} {refname:<16} {subject}"

            is_head = (refname == head_branch)
            data = {'refname': refname, 'is_head': is_head}

            if is_head:
                lt = LINE_MAIN_GRAPH
            else:
                lt = LINE_DEFAULT

            self.lines.append(TigLine(text, lt, data))

        self.loaded = True
        self.cursor = 0
        self.offset = 0

    def draw_line(self, win, y, line, is_cursor):
        max_w = self.width - 1

        if is_cursor:
            attr = curses.color_pair(CP_CURSOR) | curses.A_BOLD
        elif line.line_type == LINE_HEADER:
            attr = curses.color_pair(CP_HEADER) | curses.A_BOLD
        elif line.data and line.data.get('is_head'):
            attr = curses.color_pair(CP_MAIN_HEAD) | curses.A_BOLD
        else:
            attr = curses.color_pair(CP_DEFAULT)

        text = line.text
        if self.col_offset:
            text = text[self.col_offset:] if len(text) > self.col_offset else ""

        try:
            win.addstr(y, 0, text[:max_w], attr)
            if is_cursor:
                remaining = max_w - min(len(text), max_w)
                if remaining > 0:
                    win.addstr(' ' * remaining, attr)
        except curses.error:
            pass

    def get_status_info(self):
        total = len(self.lines)
        line_num = self.cursor + 1
        return f"[refs] All references"

    def enter(self):
        line = self.get_selected_line()
        if line and line.data and line.data.get('refname'):
            return ('open_main', [line.data['refname']])
        return None

