class TigApp:
    """Main tig application."""

    def __init__(self, stdscr):
        self.stdscr = stdscr
        self.height, self.width = stdscr.getmaxyx()
        self.views = []  # Stack of views
        self.active_view_idx = 0
        self.split = False
        self.status_msg = ""
        self.status_msg_time = 0
        self.cwd = None
        self.search_mode = False
        self.search_str = ""
        self.search_forward = True
        self.cmd_mode = False
        self.cmd_str = ""
        self.running = True
        self.view_stack = []  # Stack of (view, focus)
        self.prompt_view = None  # Second view in split

    def run(self, initial_view, args=None):
        """Main run loop."""
        init_colors()

        curses.curs_set(0)
        self.stdscr.keypad(True)
        curses.noecho()
        curses.cbreak()

        # Set up the initial view
        self.views = [initial_view]
        self.active_view_idx = 0
        self.resize_views()

        initial_view.refresh()
        self.draw_status()
        curses.doupdate()

        while self.running:
            try:
                key = self.stdscr.getch()
                self.handle_key(key)
                self.redraw()
            except KeyboardInterrupt:
                break
            except curses.error:
                pass

    def resize_views(self):
        """Resize all views to fit the screen."""
        self.height, self.width = self.stdscr.getmaxyx()

        if len(self.views) == 1 or not self.split:
            # Single view takes up most of the screen
            view = self.views[self.active_view_idx]
            # Leave one row for status bar
            view_height = self.height - 1
            view.resize(view_height, self.width, 0, 0)
        elif len(self.views) >= 2:
            # Split view
            if self.width >= 160:
                # Vertical split
                left_w = self.width // 2
                right_w = self.width - left_w
                self.views[0].resize(self.height - 1, left_w, 0, 0)
                self.views[1].resize(self.height - 1, right_w, 0, left_w)
            else:
                # Horizontal split
                top_h = (self.height - 1) * 2 // 3
                bot_h = self.height - 1 - top_h
                if bot_h < 4:
                    bot_h = 4
                    top_h = self.height - 1 - bot_h
                self.views[0].resize(top_h, self.width, 0, 0)
                self.views[1].resize(bot_h, self.width, top_h, 0)

    def get_active_view(self):
        if self.views:
            return self.views[self.active_view_idx]
        return None

    def redraw(self):
        """Redraw everything."""
        self.stdscr.erase()

        for i, view in enumerate(self.views):
            view.refresh()
            # Draw title bar for each view in split mode
            if self.split and len(self.views) > 1:
                self.draw_title(view, is_focus=(i == self.active_view_idx))

        if not self.split or len(self.views) == 1:
            view = self.get_active_view()
            if view:
                self.draw_title(view, is_focus=True)

        self.draw_status()
        curses.doupdate()

    def draw_title(self, view, is_focus=True):
        """Draw the title bar for a view (actually in tig, status is at bottom)."""
        # In tig, there's no separate title bar at top for the main view
        # The view takes full height and status is at the bottom
        pass

    def draw_status(self):
        """Draw the status bar at the bottom."""
        status_y = self.height - 1

        view = self.get_active_view()
        if not view:
            return

        # Get status info from view
        status_info = view.get_status_info()
        scroll_pct = view.get_scroll_pct()

        # Check for temporary status message
        current_time = time.time()
        if self.status_msg and (current_time - self.status_msg_time) < 5:
            msg = self.status_msg
        elif self.search_mode:
            msg = None  # Handled separately
        elif self.cmd_mode:
            msg = None
        else:
            msg = None

        try:
            self.stdscr.move(status_y, 0)
            self.stdscr.clrtoeol()

            attr = curses.color_pair(CP_STATUS)

            if self.search_mode:
                prefix = "/" if self.search_forward else "?"
                prompt = f"{prefix}{self.search_str}"
                self.stdscr.addstr(status_y, 0, prompt, attr)
            elif self.cmd_mode:
                prompt = f":{self.cmd_str}"
                self.stdscr.addstr(status_y, 0, prompt, attr)
            else:
                # Build status line
                pct_str = f"{scroll_pct:3}%"

                if msg:
                    # Show temporary message
                    available = self.width - len(pct_str) - 1
                    left_part = (status_info + "  " + msg)[:available]
                else:
                    left_part = status_info

                # Right-align percentage
                if len(left_part) + len(pct_str) + 1 <= self.width:
                    padding = self.width - len(left_part) - len(pct_str) - 1
                    full_line = left_part + ' ' * padding + pct_str
                else:
                    # Truncate left part
                    avail = self.width - len(pct_str) - 1
                    full_line = left_part[:avail] + ' ' + pct_str

                self.stdscr.addstr(status_y, 0, full_line[:self.width - 1], attr)

                # Show temporary message below status if any
                if msg:
                    msg_y = status_y
                    # Actually show in status line
                    pass
        except curses.error:
            pass

        # Draw search/command input
        if self.search_mode or self.cmd_mode:
            pass  # Already drawn above
        elif self.status_msg and (current_time - self.status_msg_time) < 5:
            # Show message in status line
            try:
                msg_attr = curses.color_pair(CP_STATUS)
                full_msg = self.status_msg[:self.width - 1]
                # Append to status line
                status_str = view.get_status_info()
                pct_str = f"{scroll_pct:3}%"
                msg_line = f"{status_str}  {self.status_msg}"
                if len(msg_line) + len(pct_str) + 1 <= self.width:
                    padding = self.width - len(msg_line) - len(pct_str) - 1
                    full_line = msg_line + ' ' * padding + pct_str
                else:
                    avail = self.width - len(pct_str) - 1
                    full_line = msg_line[:avail] + ' ' + pct_str
                self.stdscr.move(status_y, 0)
                self.stdscr.clrtoeol()
                self.stdscr.addstr(status_y, 0, full_line[:self.width - 1], msg_attr)
            except curses.error:
                pass

    def set_status(self, msg):
        self.status_msg = msg
        self.status_msg_time = time.time()

    def handle_key(self, key):
        """Handle a key press."""
        view = self.get_active_view()

        # Handle search input mode
        if self.search_mode:
            self.handle_search_key(key)
            return

        # Handle command mode
        if self.cmd_mode:
            self.handle_cmd_key(key)
            return

        # Navigation keys
        if key in (ord('q'),):
            if len(self.views) > 1:
                # Close current view
                self.views.pop(self.active_view_idx)
                if self.active_view_idx >= len(self.views):
                    self.active_view_idx = len(self.views) - 1
                self.split = len(self.views) > 1
                self.resize_views()
            else:
                self.running = False

        elif key in (ord('Q'), 3):  # Q or Ctrl-C
            self.running = False

        elif key in (ord('j'), curses.KEY_DOWN, 14):  # j, Down, Ctrl-N
            if view:
                view.scroll_down()

        elif key in (ord('k'), curses.KEY_UP, 16):  # k, Up, Ctrl-P
            if view:
                view.scroll_up()

        elif key in (ord('J'),):  # J - next
            if view:
                view.scroll_down()

        elif key in (ord('K'),):  # K - previous
            if view:
                view.scroll_up()

        elif key in (curses.KEY_NPAGE, ord(' ')):  # PageDown, Space
            if view:
                view.page_down()

        elif key in (curses.KEY_PPAGE, ord('-')):  # PageUp, -
            if view:
                view.page_up()

        elif key == 21:  # Ctrl-U
            if view:
                view.half_page_up()

        elif key == 4:  # Ctrl-D
            if view:
                view.half_page_down()

        elif key == curses.KEY_HOME:
            if view:
                view.first_line()

        elif key == curses.KEY_END:
            if view:
                view.last_line()

        elif key in (curses.KEY_LEFT,):
            if view:
                view.scroll_left()

        elif key in (curses.KEY_RIGHT,):
            if view:
                view.scroll_right()

        elif key == ord('|'):
            if view:
                view.scroll_first_col()

        elif key in (curses.KEY_IC, 25):  # Insert or Ctrl-Y
            if view:
                view.scroll_line_up()

        elif key in (curses.KEY_DC, 5):  # Delete or Ctrl-E
            if view:
                view.scroll_line_down()

        elif key == ord('\n') or key == curses.KEY_ENTER or key == 10:
            if view:
                result = view.enter()
                if result:
                    self.handle_action(result)

        elif key == ord('<'):
            # Go back
            if len(self.views) > 1:
                self.views.pop(self.active_view_idx)
                if self.active_view_idx >= len(self.views):
                    self.active_view_idx = len(self.views) - 1
                self.split = len(self.views) > 1
                self.resize_views()

        elif key == ord('\t'):  # Tab - switch between views
            if len(self.views) > 1:
                self.active_view_idx = (self.active_view_idx + 1) % len(self.views)

        elif key in (ord('R'), curses.KEY_F5):
            if view:
                self.reload_view(view)

        elif key == ord('O'):
            # Maximize current view
            if self.split:
                self.split = False
                self.views = [self.views[self.active_view_idx]]
                self.active_view_idx = 0
                self.resize_views()

        elif key == 12:  # Ctrl-L
            self.stdscr.clear()
            self.resize_views()

        elif key == ord('/'):
            self.search_mode = True
            self.search_forward = True
            self.search_str = ""

        elif key == ord('?'):
            self.search_mode = True
            self.search_forward = False
            self.search_str = ""

        elif key == ord('n'):
            if view and view.search_pattern:
                result = view.search(view.search_pattern, forward=True)
                if result and result[0] >= 0:
                    match_line, count = result
                    self.set_status(f"Line {match_line + 1} matches '{view.search_pattern}' (1 of {count})")

        elif key == ord('N'):
            if view and view.search_pattern:
                result = view.search(view.search_pattern, forward=False)
                if result and result[0] >= 0:
                    match_line, count = result
                    self.set_status(f"Line {match_line + 1} matches '{view.search_pattern}' (1 of {count})")

        elif key == ord(':'):
            self.cmd_mode = True
            self.cmd_str = ""

        # View switching
        elif key == ord('m'):
            self.switch_to_main()

        elif key == ord('d'):
            self.switch_to_diff()

        elif key == ord('l'):
            self.switch_to_log()

        elif key == ord('L'):
            self.switch_to_reflog()

        elif key == ord('t'):
            self.switch_to_tree()

        elif key == ord('f'):
            self.switch_to_blob()

        elif key == ord('b'):
            self.switch_to_blame()

        elif key in (ord('r'),):
            self.switch_to_refs()

        elif key in (ord('s'), ord('S')):
            self.switch_to_status()

        elif key == ord('y'):
            self.switch_to_stash()

        elif key == ord('g'):
            self.switch_to_grep()

        elif key == ord('p'):
            self.switch_to_pager()

        elif key == ord('h'):
            self.switch_to_help()

        elif key == ord('v'):
            self.set_status(f"tig version {VERSION}")

        elif key == curses.KEY_RESIZE:
            self.height, self.width = self.stdscr.getmaxyx()
            self.resize_views()
            self.stdscr.clear()

    def handle_search_key(self, key):
        """Handle key in search mode."""
        if key == 27:  # Escape
            self.search_mode = False
            self.search_str = ""
        elif key in (ord('\n'), 10, curses.KEY_ENTER):
            self.search_mode = False
            if self.search_str:
                view = self.get_active_view()
                if view:
                    result = view.search(self.search_str, forward=self.search_forward)
                    if result:
                        match_line, count = result
                        if match_line >= 0:
                            self.set_status(f"Line {match_line + 1} matches '{self.search_str}' (1 of {count})")
                        else:
                            self.set_status(f"No match for '{self.search_str}'")
        elif key in (curses.KEY_BACKSPACE, 127, 8):
            if self.search_str:
                self.search_str = self.search_str[:-1]
        elif 32 <= key <= 126:
            self.search_str += chr(key)

    def handle_cmd_key(self, key):
        """Handle key in command mode."""
        if key == 27:  # Escape
            self.cmd_mode = False
            self.cmd_str = ""
        elif key in (ord('\n'), 10, curses.KEY_ENTER):
            self.cmd_mode = False
            self.execute_command(self.cmd_str)
            self.cmd_str = ""
        elif key in (curses.KEY_BACKSPACE, 127, 8):
            if self.cmd_str:
                self.cmd_str = self.cmd_str[:-1]
            else:
                self.cmd_mode = False
        elif 32 <= key <= 126:
            self.cmd_str += chr(key)

    def execute_command(self, cmd):
        """Execute a tig command."""
        cmd = cmd.strip()
        if not cmd:
            return

        if cmd == 'q' or cmd == 'quit':
            self.running = False
        elif cmd.startswith('toggle '):
            opt = cmd[7:].strip()
            self.set_status(f"Toggled {opt}")
        else:
            self.set_status(f"Unknown command: {cmd}")

    def handle_action(self, result):
        """Handle action returned from view.enter()."""
        if not result:
            return

        action = result[0]

        if action == 'open_diff':
            commit_id = result[1]
            diff_view = DiffView(self)
            diff_view.load(commit_id, cwd=self.cwd)
            self.push_view(diff_view)

        elif action == 'open_main':
            rev_args = result[1] if len(result) > 1 else None
            main_view = MainView(self)
            main_view.load(rev_args=rev_args, cwd=self.cwd)
            self.push_view(main_view)

        elif action == 'open_tree':
            commit_id = result[1]
            path = result[2] if len(result) > 2 else ""
            tree_view = TreeView(self)
            tree_view.load(commit_id=commit_id, path=path, cwd=self.cwd)
            self.push_view(tree_view)

        elif action == 'open_blob':
            blob_hash = result[1]
            filename = result[2] if len(result) > 2 else None
            blob_view = BlobView(self)
            blob_view.load(blob_hash, filename=filename, cwd=self.cwd)
            self.push_view(blob_view)

        elif action == 'open_blob_file':
            filename = result[1]
            out, _, rc = run_git(['show', f'HEAD:{filename}'], cwd=self.cwd)
            if rc == 0:
                blob_view = BlobView(self)
                blob_view.lines = [TigLine(l) for l in out.splitlines()]
                blob_view.loaded = True
                blob_view.filename = filename
                self.push_view(blob_view)

